package fraymus.workspace;

import fraymus.factory.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;

/** Declared lifecycle fixtures; the111 Electron study supplies real rendered outcomes. */
public class GoalArchive111Test {
    static JSONObject request(WorkflowTest.Fixture f){var h=f.workflows.childHistory111();var ids=new JSONArray();for(Object item:h.getJSONArray("records")){var row=(JSONObject)item;if(row.getBoolean("eligible"))ids.put(row.getString("id"));}return new JSONObject().put("planSha256",h.getString("planSha256")).put("ids",ids);}
    static Map<String,String> payloads(Path root)throws Exception{var schemas=new SchemaRegistry();for(String type:List.of("goal","procedure"))schemas.register(new ComponentSchema("workspace."+type,1,Map.of("payload",ComponentSchema.Kind.TEXT),Set.of("payload")));var out=new TreeMap<String,String>();for(var e:new WorldCheckpointStore(root.resolve("goals/tasks.fworld")).load(schemas).snapshot().entities())if(e.components().getFirst().type().equals("workspace.goal"))out.put(e.id().toString(),e.components().getFirst().values().get("payload"));return out;}
    static Path file(WorkflowTest.Fixture f,String id){return f.root.resolve("goals/archive111/"+f.workflows.readChild111(id).getJSONObject("archive111").getString("sha256")+".json");}
    @Test public void exactGoalBytesAndOwnedReferencesSurviveColdRecheck()throws Exception{
        Path root=Files.createTempDirectory("goals111-exact-");Map<String,String> original;String parent;
        try(var f=new WorkflowTest.Fixture(root)){parent=Archive110Test.completed(f).getString("id");original=payloads(root);var workflows=Files.readAllBytes(root.resolve("workflows/tasks.fworld"));var bank=f.goals.procedures();var receipt=f.workflows.archiveChildren111(request(f));assertEquals(12,receipt.getInt("archived"));assertEquals(0,f.goals.list().length());assertTrue(bank.similar(f.goals.procedures()));assertArrayEquals(workflows,Files.readAllBytes(root.resolve("workflows/tasks.fworld")));for(var entry:original.entrySet()){assertEquals(entry.getValue(),Files.readString(file(f,entry.getKey())));assertTrue(new JSONObject(entry.getValue()).similar(f.goals.read(entry.getKey())));assertTrue(f.workflows.verifyChild111(entry.getKey()).getBoolean("passed"));assertThrows(IllegalStateException.class,()->f.goals.resume(entry.getKey()));}}
        try(var f=new WorkflowTest.Fixture(root)){assertEquals(0,f.goals.list().length());assertTrue(f.workflows.verifyArchive110(parent).getBoolean("passed"));var next=Qualification105Test.finish(f,Qualification105Test.start(f,"after-goal-archive").getString("id"));assertEquals(next.toString(),"completed",next.getString("status"));assertEquals(5,next.getJSONObject("metrics").getInt("reusedExamples"));assertEquals(2,f.goals.list().length());assertEquals(12,f.workflows.childHistory111().getInt("archived"));for(var entry:original.entrySet())assertEquals(entry.getValue(),Files.readString(file(f,entry.getKey())));}
    }
    @Test public void missingCorruptAndNonFileArchiveRefuseWithOriginalCheckpoint()throws Exception{
        Path root=Files.createTempDirectory("goals111-corrupt-");Path archive;byte[] bytes;String id;
        try(var f=new WorkflowTest.Fixture(root)){Archive110Test.completed(f);id=request(f).getJSONArray("ids").getString(0);f.workflows.archiveChildren111(request(f));archive=file(f,id);bytes=Files.readAllBytes(archive);byte[] checkpoint=Files.readAllBytes(root.resolve("goals/tasks.fworld"));var altered=bytes.clone();altered[altered.length-2]^=1;Files.write(archive,altered);assertThrows(IllegalStateException.class,()->f.goals.read(id));assertThrows(IllegalStateException.class,()->Qualification105Test.start(f,"bad-archive"));assertArrayEquals(checkpoint,Files.readAllBytes(root.resolve("goals/tasks.fworld")));Files.write(archive,bytes);assertTrue(f.workflows.verifyChild111(id).getBoolean("passed"));Files.delete(archive);assertThrows(IllegalStateException.class,()->f.goals.read(id));Files.write(archive,bytes);}
        Files.delete(archive);assertThrows(IllegalStateException.class,()->{try(var f=new WorkflowTest.Fixture(root)){fail("Missing archived child ignored");}});Files.write(archive,bytes);try(var f=new WorkflowTest.Fixture(root)){assertTrue(f.workflows.verifyChild111(id).getBoolean("passed"));}
        // Directory substitution is rejected without relying on OS symbolic-link privileges.
        Files.delete(archive);Files.createDirectory(archive);try{assertThrows(IllegalStateException.class,()->{try(var f=new WorkflowTest.Fixture(root)){fail("Non-file archive accepted");}});}finally{Files.delete(archive);Files.write(archive,bytes);}
    }
    @Test public void revisedOriginalReportStillRefusesAfterGoalArchive()throws Exception{
        try(var f=new WorkflowTest.Fixture(Files.createTempDirectory("goals111-report-"))){var parent=Archive110Test.completed(f);String workflow=parent.getJSONArray("stages").getJSONObject(0).getString("workflowId"),id=f.workflows.read(workflow).getJSONArray("stages").getJSONObject(1).getString("goalId");f.workflows.archiveChildren111(request(f));var ref=f.goals.read(id).getJSONObject("report");f.artifacts.write(new JSONObject().put("id",ref.getString("id")).put("expectedVersion",1).put("title","Deliberately revised original").put("files",new JSONObject().put("index.html","<html><body>Changed111</body></html>")));assertThrows(IllegalStateException.class,()->f.workflows.verifyChild111(id));assertThrows(IllegalStateException.class,()->Qualification105Test.start(f,"changed-original"));assertEquals(1,f.goals.procedures().length());assertEquals(0,f.goals.list().length());}
    }
    @Test public void revisedSourceStillRefusesAfterGoalArchive()throws Exception{
        try(var f=new WorkflowTest.Fixture(Files.createTempDirectory("goals111-source-"))){var parent=Archive110Test.completed(f);var w=f.workflows.read(parent.getJSONArray("stages").getJSONObject(0).getString("workflowId"));String id=w.getJSONArray("stages").getJSONObject(0).getString("goalId");f.workflows.archiveChildren111(request(f));var d=f.data.read(w.getJSONObject("dataBinding").getString("datasetId"),1);var in=new JSONObject();for(String key:List.of("title","filename","csv","sourceKind","sourceNote","missingPolicy","mapping"))in.put(key,d.get(key));f.data.importCsv(in.put("id",d.getString("datasetId")).put("expectedVersion",1));assertThrows(IllegalStateException.class,()->f.workflows.verifyChild111(id));assertThrows(IllegalStateException.class,()->Qualification105Test.start(f,"changed-source"));}
    }
    @Test public void staleInvalidActiveAndCancelledRequestsNeverCommit()throws Exception{
        try(var f=new WorkflowTest.Fixture(Files.createTempDirectory("goals111-stale-"))){Archive110Test.completed(f);var in=request(f);byte[] before=Files.readAllBytes(f.root.resolve("goals/tasks.fworld"));var stale=WorldFrames.copy(in).put("planSha256","0".repeat(64));var duplicate=WorldFrames.copy(in).put("ids",new JSONArray().put(in.getJSONArray("ids").get(0)).put(in.getJSONArray("ids").get(0)));var foreign=WorldFrames.copy(in).put("ids",new JSONArray().put(UUID.randomUUID().toString()));assertThrows(IllegalStateException.class,()->f.workflows.archiveChildren111(stale));assertThrows(IllegalArgumentException.class,()->f.workflows.archiveChildren111(duplicate));assertThrows(IllegalStateException.class,()->f.workflows.archiveChildren111(foreign));assertThrows(IllegalArgumentException.class,()->f.workflows.archiveChildren111(WorldFrames.copy(in).put("force",true)));assertArrayEquals(before,Files.readAllBytes(f.root.resolve("goals/tasks.fworld")));f.workflows.archiveChildren111(in);assertThrows(IllegalStateException.class,()->f.workflows.archiveChildren111(in));
            String pending=Qualification105Test.start(f,"unfinished-parent").getString("id");assertThrows(IllegalStateException.class,()->f.workflows.archiveChildren111(in));f.workflows.cancel(pending);assertEquals(0,request(f).getJSONArray("ids").length());}
    }
    @Test public void preparedGoalFilesWithoutCommitRetainActiveBytesAndRetry()throws Exception{
        Path root=Files.createTempDirectory("goals111-atomic-");Map<String,String> originals;
        try(var f=new WorkflowTest.Fixture(root)){Archive110Test.completed(f);originals=payloads(root);Path previous=root.resolve("goals/tasks.fworld.previous"),backup=root.resolve("goals/before-archive.backup");Files.move(previous,backup);Files.createDirectory(previous);Files.writeString(previous.resolve("block"),"Declared checkpoint failure");byte[] before=Files.readAllBytes(root.resolve("goals/tasks.fworld"));assertThrows(Exception.class,()->f.workflows.archiveChildren111(request(f)));assertArrayEquals(before,Files.readAllBytes(root.resolve("goals/tasks.fworld")));assertEquals(originals,payloads(root));assertEquals(12,f.goals.list().length());Files.delete(previous.resolve("block"));Files.delete(previous);Files.move(backup,previous);}
        try(var f=new WorkflowTest.Fixture(root)){assertEquals(12,f.goals.list().length());f.workflows.archiveChildren111(request(f));for(var entry:originals.entrySet())assertEquals(entry.getValue(),Files.readString(file(f,entry.getKey())));assertEquals(0,f.goals.list().length());}
    }
    @Test public void activeBudgetRemains64AndCancelledStandaloneGoalsStayActive()throws Exception{
        try(var f=new WorkflowTest.Fixture(Files.createTempDirectory("goals111-budget-"))){Archive110Test.completed(f);f.workflows.archiveChildren111(request(f));var d=f.source("t,x\n0,0\n0.1,0.002\n");var in=new JSONObject().put("datasetId",d.getString("datasetId")).put("datasetVersion",1);for(int i=0;i<64;i++){var g=f.goals.startData(in);f.goals.cancel(g.getString("id"));}assertEquals(64,f.goals.list().length());assertEquals(12,f.workflows.childHistory111().getInt("archived"));assertEquals(0,request(f).getJSONArray("ids").length());assertThrows(IllegalStateException.class,()->f.goals.startData(in));assertThrows(IllegalStateException.class,()->f.goals.workflowCapacity());}
    }
    @Test public void retainedImplementationReadsArchivedChildrenAndVerifiesFreshInputs()throws Exception{
        try(var f=new WorkflowTest.Fixture(Files.createTempDirectory("goals111-reuse-"))){var parent=Archive110Test.completed(f);var selected=f.workflows.read(parent.getJSONArray("stages").getJSONObject(5).getString("workflowId"));f.workflows.archiveChildren111(request(f));f.workflows.archive110(Archive110Test.request(f));var data=f.source("t,x\n0,0.2\n0.2,0.1\n0.4,0.3\n");var w=f.workflows.reuse(Implementation103Test.args(selected,data));var e=DataSummary104Test.audit(f,w.getString("id"));DataCreation101Test.ack(f,e,DataSummary102Test.observed(f,e,data));assertEquals("completed",DataCreation101Test.finish(f,w.getString("id")).getString("status"));assertEquals(2,f.goals.list().length());assertEquals(12,f.workflows.childHistory111().getInt("archived"));assertTrue(f.workflows.verifyArchive110(parent.getString("id")).getBoolean("passed"));}
    }
}
